{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.REF_CATEGORY_PRICE_SLABS_META AS WITH SKU_META AS ( SELECT REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\') AS CLEAN_SKU_GROUP, COALESCE( MAX( CASE WHEN MF.CATEGORY IS NOT NULL AND TRIM(MF.CATEGORY) <> \'\' THEN CASE WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\', \'CHINO TROUSER\', \'CHINO TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'DENIM\', \'DENIMS\', \'DEMIN\', \'DEMINS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'TSHIRT\', \'T SHIRT\', \'T-SHIRT\', \'T-SHIRTS\', \'POLO\', \'POLOS\') THEN \'T-SHIRTS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'OVERSHIRTS\', \'OVER SHIRT\', \'OVERSHIRT\') THEN \'OVERSHIRT\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'SWEAT SHIRT\', \'SWEAT SHIRTS\', \'SWEATSHIRT\', \'SWEATSHIRTS\') THEN \'SWEATSHIRTS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'TRACKPANTS\', \'TRACK PANTS\', \'JOGGER\', \'JOGGERS\', \'JOGGERS & TRACKPANTS\') THEN \'JOGGERS AND TRACKPANTS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'CARGO\', \'CARGOS\', \'CARGO PANTS\') THEN \'CARGO PANTS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'COORD\', \'COORDS\', \'CO-ORD\', \'CO-ORDS\') THEN \'COORDS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'BOXER\', \'BOXERS\') THEN \'BOXERS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'BAG\', \'BAGS\', \'BACKPACK\', \'BACKPACKS\') THEN \'BAGS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'PERFUME\', \'PERFUMES\', \'FRAGRANCE\') THEN \'PERFUMES\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'SUNGLASS\', \'SUNGLASSES\', \'GOGGLES\') THEN \'SUNGLASSES\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'BELT\', \'BELTS\') THEN \'BELTS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'SHOE\', \'SHOES\', \'SNEAKER\', \'SNEAKERS\', \'FOOTWEAR\') THEN \'SHOES\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'SOCK\', \'SOCKS\', \'ACCESSORY\', \'ACCESSORIES\', \'CAP\', \'CAPS\') THEN \'ACCESSORIES\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'SUIT\', \'SUITS\', \'BLAZER\', \'BLAZERS\', \'SUITS & BLAZERS\') THEN \'SUITS & BLAZERS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'JACKET\', \'JACKETS\') THEN \'JACKETS\' ELSE UPPER(TRIM(MF.CATEGORY)) END ELSE NULL END ), MAX( CASE WHEN UPPER(MF.SKU_GROUP) LIKE \'4MST%\' OR UPPER(MF.SKU_GROUP) LIKE \'4LPL%\' OR UPPER(MF.SKU_GROUP) LIKE \'4LRN%\' OR UPPER(MF.SKU_GROUP) LIKE \'4BPL%\' OR UPPER(MF.SKU_GROUP) LIKE \'4BRN%\' THEN \'T-SHIRTS\' WHEN UPPER(MF.SKU_GROUP) LIKE \'4MSS%\' OR UPPER(MF.SKU_GROUP) LIKE \'4LSH%\' OR UPPER(MF.SKU_GROUP) LIKE \'4BSH%\' THEN \'SHIRTS\' WHEN UPPER(MF.SKU_GROUP) LIKE \'4MJN%\' OR UPPER(MF.SKU_GROUP) LIKE \'4BJN%\' THEN \'JEANS\' WHEN UPPER(MF.SKU_GROUP) LIKE \'4MTR%\' OR UPPER(MF.SKU_GROUP) LIKE \'4BTR%\' OR UPPER(MF.SKU_GROUP) LIKE \'4MCN%\' OR UPPER(MF.SKU_GROUP) LIKE \'4BCN%\' THEN \'TROUSERS\' WHEN UPPER(MF.SKU_GROUP) LIKE \'4MCG%\' THEN \'CARGO PANTS\' WHEN UPPER(MF.SKU_GROUP) LIKE \'4MCD%\' THEN \'COORDS\' WHEN UPPER(MF.SKU_GROUP) LIKE \'4MSW%\' THEN \'SWEATSHIRTS\' WHEN UPPER(MF.SKU_GROUP) LIKE \'4MOS%\' THEN \'OVERSHIRT\' ELSE \'OTHERS\' END ) ) AS CATEGORY, COALESCE(MAX( CASE WHEN UPPER(MF.STYLE) LIKE \'%LUXE%\' OR UPPER(MF.SKU_GROUP) LIKE \'4MLX%\' OR UPPER(MF.SKU_GROUP) LIKE \'4LRN%\' OR UPPER(MF.SKU_GROUP) LIKE \'4LPL%\' THEN \'LUXE\' WHEN UPPER(MF.STYLE) LIKE \'%PLUS%\' OR UPPER(MF.SKU_GROUP) LIKE \'4MBG%\' OR UPPER(MF.SKU_GROUP) LIKE \'4BRN%\' OR UPPER(MF.SKU_GROUP) LIKE \'4BPL%\' THEN \'PLUS\' ELSE \'SNITCH\' END ), \'SNITCH\') AS STYLE, COALESCE(MAX( CASE WHEN UPPER(MF.CATEGORY) = \'T-SHIRTS\' THEN CASE WHEN TRIM(LOWER(MF.COLLAR_NEW)) IN (\'polo\',\'cuban\',\'baseball\',\'mandarin\',\'mock\',\'high neck\',\'zip\',\'spread\') THEN \'POLO\' ELSE \'ROUND\' END WHEN UPPER(MF.CATEGORY) = \'SHIRTS\' THEN CASE WHEN LOWER(MF.STYLE) LIKE \'%linen%\' OR UPPER(MF.MATERIAL_NEW) = \'LINEN\' THEN \'LINEN\' WHEN UPPER(MF.MATERIAL_NEW) = \'COTTON\' THEN \'COTTON\' ELSE \'POLYESTER\' END WHEN UPPER(MF.CATEGORY) IN (\'TROUSERS\', \'CHINOS\', \'CHINO\') THEN CASE WHEN UPPER(MF.FIT) IN (\'SLIM FIT\') THEN \'SLIM FIT\' ELSE \'STRAIGHT FIT\' END WHEN UPPER(MF.CATEGORY) = \'JEANS\' THEN CASE WHEN UPPER(MF.FIT) = \'SLIM FIT\' THEN \'SLIM FIT\' WHEN UPPER(MF.FIT) = \'SKINNY FIT\' THEN \'SKINNY FIT\' ELSE \'STRAIGHT FIT\' END END ), \'NA\') AS META1, COALESCE(MAX( CASE WHEN UPPER(MF.CATEGORY) = \'T-SHIRTS\' THEN CASE WHEN UPPER(TRIM(MF.STYLE)) LIKE \'%TECHNICAL%\' THEN \'TECHNICAL\' WHEN UPPER(TRIM(MF.DESIGNS)) = \'SOLID\' THEN \'CORE\' ELSE \'FASHION\' END WHEN UPPER(MF.CATEGORY) = \'SHIRTS\' THEN CASE WHEN UPPER(TRIM(MF.DESIGNS)) = \'SOLID\' THEN \'SOLID\' WHEN UPPER(TRIM(MF.DESIGNS)) = \'STRIPES\' THEN \'STRIPES\' ELSE \'PRINTED\' END END ), \'NA\') AS META2, COALESCE(MAX( CASE WHEN UPPER(MF.CATEGORY) = \'T-SHIRTS\' THEN CASE WHEN UPPER(TRIM(MF.FIT)) IN (\'OVERSIZED\',\'BOX FIT\',\'RELAXED FIT\') THEN \'OVERSIZED FIT\' WHEN UPPER(TRIM(MF.FIT)) = \'SLIM FIT\' THEN \'SLIM FIT\' ELSE \'REGULAR FIT\' END END ), \'NA\') AS META3 FROM SNITCH_DB.MAPLEMONK.METAFIELDS_DATA MF GROUP BY REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\') ), SKU_MRP AS ( SELECT REGEXP_REPLACE(UPPER(TRIM( CASE WHEN UPPER(\"Item SkuCode\") LIKE \'4C-%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) ELSE \"Item SkuCode\" END )), \'[^A-Z0-9]\', \'\') AS CLEAN_SKU_GROUP, MAX(TRY_CAST(MRP AS FLOAT)) AS MRP FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_LIVE_INVENTORY WHERE TRY_CAST(MRP AS FLOAT) IS NOT NULL AND TRY_CAST(MRP AS FLOAT) > 0 GROUP BY 1 ), COMBO_PRICE_BOUNDS AS ( SELECT M.CATEGORY, M.STYLE, M.META1, M.META2, M.META3, FLOOR(MIN(U.MRP) / 200) * 200 AS BASE_MIN_PRICE, CEIL(MAX(U.MRP) / 200) * 200 AS BASE_MAX_PRICE FROM SKU_META M INNER JOIN SKU_MRP U ON M.CLEAN_SKU_GROUP = U.CLEAN_SKU_GROUP WHERE M.CATEGORY IS NOT NULL AND UPPER(TRIM(M.CATEGORY)) NOT IN (\'NT\', \'CB\', \'OTHERS\', \'NA\', \'\') GROUP BY 1, 2, 3, 4, 5 ), SLAB_STEPS AS ( SELECT ROW_NUMBER() OVER (ORDER BY NULL) - 1 AS STEP_IDX FROM TABLE(GENERATOR(ROWCOUNT => 20)) ), GENERATED_SLABS AS ( SELECT B.CATEGORY, B.STYLE, B.META1, B.META2, B.META3, (B.BASE_MIN_PRICE + (S.STEP_IDX * 200)) AS SLAB_MIN_PRICE, CASE WHEN (B.BASE_MIN_PRICE + ((S.STEP_IDX + 1) * 200)) >= GREATEST(B.BASE_MAX_PRICE, B.BASE_MIN_PRICE + 200) THEN 999999 ELSE (B.BASE_MIN_PRICE + (S.STEP_IDX * 200) + 199) END AS SLAB_MAX_PRICE, DENSE_RANK() OVER ( PARTITION BY B.CATEGORY, B.STYLE, B.META1, B.META2, B.META3 ORDER BY (B.BASE_MIN_PRICE + (S.STEP_IDX * 200)) ASC ) AS SLAB_NUM FROM COMBO_PRICE_BOUNDS B CROSS JOIN SLAB_STEPS S WHERE (B.BASE_MIN_PRICE + (S.STEP_IDX * 200)) < GREATEST(B.BASE_MAX_PRICE, B.BASE_MIN_PRICE + 200) ) SELECT CATEGORY, STYLE, META1, META2, META3, CONCAT(\'SLAB_\', SLAB_NUM) AS PRICE_SLAB_CODE, CASE WHEN SLAB_MAX_PRICE = 999999 THEN CONCAT(\'₹\', CAST(SLAB_MIN_PRICE AS INT), \'+\') ELSE CONCAT(\'₹\', CAST(SLAB_MIN_PRICE AS INT), \' – ₹\', CAST(SLAB_MAX_PRICE AS INT)) END AS PRICE_RANGE_LABEL, SLAB_MIN_PRICE, SLAB_MAX_PRICE, CURRENT_TIMESTAMP() AS CREATED_AT FROM GENERATED_SLABS WHERE UPPER(TRIM(CATEGORY)) NOT IN (\'NT\', \'CB\', \'OTHERS\', \'NA\', \'\') QUALIFY ROW_NUMBER() OVER ( PARTITION BY CATEGORY, STYLE, META1, META2, META3, SLAB_MIN_PRICE ORDER BY SLAB_NUM ASC ) = 1;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            